import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { DetailsView, RunRecord, SetupState, TestRun, UnitySnapshot } from '../types'
import { K, icon, logo, statusMark, toneGlyphText, toneKey } from './art'
import type { IconName, Tone } from './art'
import {
  BUILD_GRACE_MS, DETAIL_VIEWS, GHOST_MS, HISTORY_SIZE, actionFor, ago, bar, buttonsFor, canUnblock, capitalize, cardsFor,
  clock, compileFailedIn, currentGroup, detailRows, detailsTitle, editorBadge, filled, initial, isHungAnswer,
  mergePoll, minutes, note, parseCliOutput, parseConsole, parseGit, readConfig, shortTest, statusLine, toneGlyph, working,
} from './core'
import type { ActionKey, CliAnswer, Config, SuiteRecord, View } from './core'
import { pick } from './strings'
import type { BusyKind, Lang, Strings } from './strings'

// The Unity project the session sits in, watched through the Unity CLI and the
// editor's Pipeline package: the editor's state, the test runner, the build,
// the console, the last APK/AAB and the git tree, in a pane, on the status line
// and as toasts. When something is missing (the CLI, the Pipeline package, the
// project's editor version, a running editor) the pane says so and offers the
// one-click fix. The decisions live in core.ts; this file reads and draws.

const PANE = 'unity'
const POLL_MS = 5000
/** Slow facts (git, console, setup) are read every this many polls. */
const SLOW_EVERY = 6
const LOG_TAIL_LINES = 400
/** Below this many cells across, the dashboard stacks its cards two by two. */
const NARROW_COLUMNS = 90
/** How long a first press on "Stop the tests" waits for the second. */
const ARM_MS = 5000

// Unity's own installers; with no channel set they take the stable release, or the beta until one ships.
const CLI_INSTALL_WINDOWS = 'irm https://public-cdn.cloud.unity3d.com/hub/prod/cli/install.ps1 | iex'
const CLI_INSTALL_UNIX = 'curl -fsSL https://public-cdn.cloud.unity3d.com/hub/prod/cli/install.sh | bash'

const snapshot = atom({ plugin: 'unity-watch', key: 'snapshot' } as const, initial)
/** Which card's details the dashboard shows under the cards, if any. */
const details = atom({ plugin: 'unity-watch', key: 'details' } as const, 'none' as DetailsView)

// ---------- module state: a reload starts it over, and session.start finds it again ----------

let cfg: Config = readConfig({})
/** The words in use; `auto` settles on the machine's language at session start. */
let t: Strings = pick('en')
let isWindows = false
let root: string | null = null
let projectName = ''
let cliPath: string | null = null
let editorVersion: string | undefined
let editorPath: string | undefined
/** The editor log this machine writes to: the project's own, or the editor's default one. */
let logPath: string | undefined

let polling = false
let tick = 0
let ghostSince = 0
let lastLogMtime = 0
let lastLogChange = 0
/** Polls in a row the editor did not answer: one miss is a busy editor (an import, a domain reload), two a closed one. */
let misses = 0
/** The action a button started in this module's life (start() clears the state's copy a reload leaves). */
let acting: BusyKind | null = null
/** Until when a first press on "Stop the tests" waits for the second one (ms since epoch). */
let armedUntil = 0

const slash = (p: string) => p.replace(/\\/g, '/').replace(/\/+$/, '')
const historyKey = () => `history:${root}`
const suiteKey = () => `suite:${root}`

function view(now: number): View {
  return { t, testMode: cfg.testMode, buildTarget: cfg.buildTarget, editorVersion, cliPath, logPath, root, armed: armedUntil > now }
}

// ---------- the machine, the project and the toolchain ----------

/** The machine's language: the POSIX locale variables, or Windows' UI culture. */
async function detectLanguage($: EngineInterface): Promise<Lang> {
  // Each name spelled out: the engine lists the variables a mod reads from its literal calls.
  const locales = [await $.env.get('LC_ALL'), await $.env.get('LC_MESSAGES'), await $.env.get('LANG'), await $.env.get('LANGUAGE')]
  for (const v of locales) {
    if (v && v.length >= 2 && v !== 'C' && v !== 'POSIX') return v.toLowerCase().startsWith('fr') ? 'fr' : 'en'
  }
  if (isWindows) {
    try {
      const run = await $.process.run(['powershell', '-NoProfile', '-Command', '(Get-UICulture).TwoLetterISOLanguageName'], { timeoutMs: 10_000 })
      return run.stdout.trim().toLowerCase() === 'fr' ? 'fr' : 'en'
    } catch {
      // keep English
    }
  }
  return 'en'
}

/** The session's folder (or its parent) when it is a Unity project: ProjectSettings/ProjectVersion.txt and Assets/. */
async function findProject($: EngineInterface): Promise<void> {
  const cwd = slash(await $.session.cwd())
  for (const dir of [cwd, cwd.replace(/\/[^/]+$/, '')]) {
    try {
      const version = await $.fs.read(`${dir}/ProjectSettings/ProjectVersion.txt`)
      const assets = await $.fs.stat(`${dir}/Assets`)
      if (assets.kind !== 'dir') continue
      root = dir
      projectName = dir.split('/').pop() ?? 'Unity'
      editorVersion = /m_EditorVersion:\s*(\S+)/.exec(version)?.[1]
      return
    } catch {
      // not this one
    }
  }
  root = null
}

/** The Unity CLI: where Unity's installers put it on each system, then whatever `unity` the PATH gives. */
async function findCli($: EngineInterface): Promise<string | undefined> {
  const local = await $.env.get('LOCALAPPDATA')
  const home = (await $.env.get('HOME')) ?? (await $.env.get('USERPROFILE'))
  const candidates = [
    local ? `${slash(local)}/Unity/bin/unity.exe` : '',
    home ? `${slash(home)}/.unity/bin/unity` : '',
    home ? `${slash(home)}/.local/bin/unity` : '',
    'unity',
  ].filter(c => c.length > 0)
  for (const c of candidates) {
    try {
      const run = await $.process.run([c, '--version'], { timeoutMs: 15_000 })
      if (run.exitCode === 0) {
        cliPath = c
        return run.stdout.trim().split('\n')[0]
      }
    } catch {
      // not there
    }
  }
  cliPath = null
  return undefined
}

async function hasPipelinePackage($: EngineInterface): Promise<boolean> {
  if (!root) return false
  try {
    return (await $.fs.read(`${root}/Packages/manifest.json`)).includes('"com.unity.pipeline"')
  } catch {
    return false
  }
}

/** The installed editor of the project's version, from the CLI's list. */
async function findEditor($: EngineInterface): Promise<void> {
  editorPath = undefined
  if (!cliPath || !editorVersion) return
  try {
    const run = await $.process.run([cliPath, 'editors', '--installed', '--json', '--no-banner'], { timeoutMs: 30_000 })
    const parsed = JSON.parse(run.stdout) as { data?: { version?: string; location?: string }[] }
    editorPath = parsed.data?.find(ed => ed.version === editorVersion)?.location
  } catch {
    // keep none
  }
}

async function readSetup($: EngineInterface): Promise<SetupState> {
  const cliVersion = await findCli($)
  await findEditor($)
  return { hasCli: cliPath !== null, cliVersion, hasPipeline: await hasPipelinePackage($), editorVersion, editorPath }
}

/** The newest of the editor logs this system may write; the ghost check needs to see it move. */
async function findLog($: EngineInterface): Promise<void> {
  const local = await $.env.get('LOCALAPPDATA')
  const home = (await $.env.get('HOME')) ?? (await $.env.get('USERPROFILE'))
  const candidates = [
    `${root}/Logs/Editor.log`,
    local ? `${slash(local)}/Unity/Editor/Editor.log` : '',
    home ? `${slash(home)}/Library/Logs/Unity/Editor.log` : '',
    home ? `${slash(home)}/.config/unity3d/Editor.log` : '',
  ].filter(c => c.length > 0)
  let best: { path: string; mtimeMs: number } | undefined
  for (const path of candidates) {
    try {
      const st = await $.fs.stat(path)
      if (!best || st.mtimeMs > best.mtimeMs) best = { path, mtimeMs: st.mtimeMs }
    } catch {
      // not on this system
    }
  }
  logPath = best?.path
}

async function logTail($: EngineInterface): Promise<string> {
  if (!logPath) return ''
  try {
    return (await $.fs.read(logPath)).split('\n').slice(-LOG_TAIL_LINES).join('\n')
  } catch {
    return ''
  }
}

/** An editor holds the project open: its lock file is there and a Unity process runs. */
async function editorRunning($: EngineInterface): Promise<boolean> {
  try {
    await $.fs.stat(`${root}/Temp/UnityLockfile`)
  } catch {
    return false
  }
  try {
    const run = isWindows
      ? await $.process.run(['tasklist', '/FI', 'IMAGENAME eq Unity.exe', '/NH'], { timeoutMs: 10_000 })
      : await $.process.run(['pgrep', '-x', 'Unity'], { timeoutMs: 10_000 })
    // tasklist also lists the lowercase unity.exe of the CLI: only the editor's own capitalised name counts.
    return isWindows ? /^Unity\.exe\s/m.test(run.stdout) : run.exitCode === 0
  } catch {
    return false
  }
}

/** An editor command through the Pipeline package (`unity cmd <args>`). */
async function cli($: EngineInterface, args: string[], timeoutMs = 60_000): Promise<CliAnswer> {
  if (!cliPath || !root) return { ok: false, error: t.cliMissing }
  try {
    const run = await $.process.run([cliPath, 'cmd', ...args, '--no-banner', '--json'], { cwd: root, timeoutMs })
    return parseCliOutput(run.stdout, t.failed)
  } catch (err) {
    return { ok: false, error: String(err) }
  }
}

// ---------- polling ----------

/** Reads everything the pane shows; `full` also reads the slow facts (git, console, setup) right away. */
async function poll($: EngineInterface, full = false) {
  if (polling || !root) return
  const projectRoot = root
  polling = true
  try {
    tick++
    const slow = full || tick % SLOW_EVERY === 1
    const prev = filled(await read($, snapshot))
    const now = await $.clock.now()
    const sameProject = prev.project?.root === projectRoot
    const base = sameProject ? prev : { ...initial, project: { root: projectRoot, name: projectName } }
    // `activity` collects this poll's own lines; mergePoll puts them on top of what stands then.
    const next: UnitySnapshot = { ...base, updatedAt: now, activity: [] }
    const clear: BusyKind[] = []
    let leaveNote: string | undefined

    if (next.history.length === 0) {
      const saved = (await $.store.get(historyKey())) as RunRecord[] | undefined
      if (Array.isArray(saved)) next.history = saved
    }
    // The toolchain rarely changes: read it at the start, slowly after, and right away while something is missing.
    const incomplete = !prev.setup || !prev.setup.hasCli || !prev.setup.hasPipeline || !prev.setup.editorPath
    if (slow || incomplete || !sameProject || !cliPath) next.setup = await readSetup($)
    const before = sameProject ? prev.setup : undefined
    if (next.setup?.hasCli && !before?.hasCli) note(next, 'ok', t.dash.cliReady, t.dash.cliReadyDetail(next.setup.cliVersion ?? '', next.setup.hasPipeline), now)
    if (next.setup?.editorPath && !before?.editorPath) note(next, 'ok', t.dash.unityFound, t.dash.unityFoundDetail(next.setup.editorVersion ?? ''), now)

    // Disk facts first: they hold even with the editor closed.
    next.apk = await newestBuild($)
    const prevApk = sameProject ? prev.apk : undefined
    if (next.apk && next.apk.mtimeMs !== prevApk?.mtimeMs) {
      note(next, 'ok', prevApk ? t.dash.newBuild : t.dash.buildFound, t.dash.buildDetail(next.apk.name, Math.round(next.apk.size / 1048576)), now)
    }
    if (slow || !logPath) await findLog($)
    if (logPath) {
      try {
        const log = await $.fs.stat(logPath)
        if (log.mtimeMs !== lastLogMtime) {
          lastLogMtime = log.mtimeMs
          lastLogChange = now
        }
      } catch {
        logPath = undefined
      }
    }
    try {
      const assets = await $.fs.list(`${projectRoot}/Assets`)
      next.initScenes = assets.filter(f => f.name.startsWith('InitTestScene') && f.name.endsWith('.unity')).length
    } catch {
      next.initScenes = 0
    }
    if (slow || !next.git || !sameProject) next.git = (await readGit($)) ?? (sameProject ? next.git : undefined)
    if (!sameProject) note(next, 'info', t.dash.projectLoaded, t.dash.projectLoadedDetail(projectName, next.git?.branch ?? '—'), now)

    const editor = cliPath ? await cli($, ['editor_status'], 20_000) : { ok: false, error: t.cliMissing }
    if (!editor.ok) {
      misses++
      // One missed answer while the editor was up is a busy editor: keep what was known and look again.
      const blip = misses < 2 && prev.isReachable && sameProject
      if (!blip) {
        next.isReachable = false
        // The editor's process still up on this project is a busy or stuck editor, not a closed one.
        next.isHung = isHungAnswer(editor) || (await editorRunning($))
        next.isCompiling = false
        next.status = undefined
        next.isGhost = false
        if (prev.isReachable && sameProject) {
          note(next, next.isHung ? 'warn' : 'bad', next.isHung ? t.dash.unityHung : t.dash.unityClosed, undefined, now)
          $.ui.toast(prev.tests.state === 'running' ? t.crashedDuringTests : next.isHung ? t.hung : t.closedOrCrashed, { timeoutMs: 10_000 })
        }
        if (next.tests.state === 'running' && !next.isHung) next.tests = { ...next.tests, state: 'idle' }
      }
    } else {
      misses = 0
      const e = (editor.result ?? {}) as { status?: string; playMode?: string; compiling?: boolean; domainReloadInProgress?: boolean }
      next.isReachable = true
      next.isHung = false
      next.status = e.status
      next.playMode = e.playMode
      const compiling = Boolean(e.compiling || e.domainReloadInProgress)
      // The compile result: when a compile just ended, and now and then for one too short to be seen.
      if (!compiling && (prev.isCompiling || slow || !sameProject)) {
        if (await checkCompile($, next, now)) leaveNote = t.compileFailedNote
      }
      next.isCompiling = compiling
      if (!prev.isReachable && prev.updatedAt > 0 && sameProject) $.ui.toast(t.answers)
      if (!prev.isReachable || !sameProject) {
        // Back from closed (even if it looked busy while it started) reads "opened"; back from a busy spell, "answers again".
        const lastDown = (prev.activity ?? []).find(a => a.title === t.dash.unityClosed || a.title === t.dash.unityHung)?.title
        const title = !sameProject || prev.updatedAt === 0 ? t.dash.unityAnswers
          : lastDown === t.dash.unityClosed || (!lastDown && !prev.isHung) ? t.dash.unityOpened : t.dash.unityBack
        note(next, 'ok', title, next.setup?.editorVersion ? `Unity ${next.setup.editorVersion}` : undefined, now)
      }
      clear.push('open')

      await pollTests($, prev, next, now, slow)
      if (await pollBuild($, prev, next, now, slow)) clear.push('build')
      if (slow || !next.console) next.console = (await readConsole($)) ?? next.console
    }

    await update($, snapshot, cur => mergePoll(cur, next, { root: projectRoot, prev, clear, leaveNote, now, t }))
    $.ui.status(cfg.statusLine ? statusLine(t, filled(await read($, snapshot)), now) : undefined)
  } finally {
    polling = false
  }
}

async function newestBuild($: EngineInterface): Promise<UnitySnapshot['apk']> {
  try {
    const files = (await $.fs.list(`${root}/Builds`)).filter(f => f.kind === 'file' && /\.(apk|aab)$/i.test(f.name))
    const top = [...files].sort((a, b) => b.mtimeMs - a.mtimeMs)[0]
    return top ? { mtimeMs: top.mtimeMs, size: top.size, name: top.name } : undefined
  } catch {
    return undefined
  }
}

async function readGit($: EngineInterface) {
  if (!root) return undefined
  try {
    const st = await $.process.run(['git', 'status', '--porcelain', '-b'], { cwd: root, timeoutMs: 20_000 })
    if (st.exitCode !== 0) return undefined
    const log = await $.process.run(['git', 'log', '-1', '--format=%h|%ct|%s'], { cwd: root, timeoutMs: 10_000 })
    return parseGit(st.stdout, log.exitCode === 0 ? log.stdout : undefined)
  } catch {
    return undefined
  }
}

async function readConsole($: EngineInterface) {
  const c = await cli($, ['console'], 20_000)
  return c.ok ? parseConsole(c.result) : undefined
}

/** Reads the last compile's result into `next`; true when it newly failed. */
async function checkCompile($: EngineInterface, next: UnitySnapshot, now: number): Promise<boolean> {
  const rc = await cli($, ['recompile_status'], 20_000)
  if (!rc.ok) return false
  const failed = compileFailedIn(rc.result)
  const was = next.compileFailed === true
  next.compileFailed = failed
  if (!failed || was) return false
  note(next, 'bad', t.dash.compileFailed, t.compileFailedNote, now)
  $.ui.toast(t.compileFailedToast, { timeoutMs: 10_000 })
  return true
}

async function pollTests($: EngineInterface, prev: UnitySnapshot, next: UnitySnapshot, now: number, slow: boolean) {
  const ts = await cli($, ['test_status'], 30_000)
  // No answer says nothing about the run: a busy editor misses one now and then mid-suite.
  if (!ts.ok) return
  const r = ts.result as
    | { status?: string; duration?: number; summary?: { total?: number; passed?: number; failed?: number }; results?: { FullName: string; Status: string }[] }
    | undefined
  const status = r?.status
  if (status === 'running') {
    const starting = prev.tests.state !== 'running'
    const tests: TestRun = { state: 'running', startedAt: starting ? now : prev.tests.startedAt, group: prev.tests.group }
    // The log can be large after a long run: read its tail only now and then.
    if (starting || slow) tests.group = currentGroup(await logTail($)) ?? prev.tests.group
    if (starting) note(next, 'info', t.dash.testsStarted, tests.group, now)
    next.tests = tests
    // A run that says "running" with the editor in edit mode and a log gone quiet is the runner's ghost;
    // without a log to watch there is no telling, so never.
    const quiet = lastLogChange > 0 && now - lastLogChange > GHOST_MS
    if (next.playMode === 'stopped' && quiet) {
      if (ghostSince === 0) ghostSince = now
    } else {
      ghostSince = 0
    }
    next.isGhost = ghostSince > 0 && now - ghostSince > GHOST_MS
    if (next.isGhost && !prev.isGhost) $.ui.toast(t.testsStuckToast, { timeoutMs: 10_000 })
    return
  }
  ghostSince = 0
  next.isGhost = false
  if (status === 'completed' || status === 'cancelled' || status === 'failed') {
    const ended = prev.tests.state === 'running'
    next.tests = {
      state: 'done',
      total: r?.summary?.total,
      passed: r?.summary?.passed,
      failed: r?.summary?.failed,
      durationS: r?.duration,
      // A run that ended before this session saw it has no known end time.
      endedAt: ended ? now : prev.tests.endedAt,
      failedNames: (r?.results ?? []).filter(x => x.Status !== 'Passed').map(x => x.FullName),
      group: prev.tests.group,
    }
    if (!ended) return
    const failed = r?.summary?.failed ?? 0
    const total = r?.summary?.total ?? 0
    const passed = r?.summary?.passed ?? 0
    if (status === 'cancelled') note(next, 'warn', t.dash.testsCancelled, undefined, now)
    else note(next, failed === 0 ? 'ok' : 'bad', failed === 0 ? t.dash.testsPassed : t.dash.testsFailed, t.dash.testsDetail(passed, total, minutes(r?.duration ?? 0)), now)
    $.ui.toast(status === 'cancelled' ? t.testsCancelled : failed === 0 ? t.testsPassed(passed, total) : t.testsFailed(failed, total), { timeoutMs: 12_000 })
    if (status !== 'cancelled' && total > 0) {
      next.history = [...next.history, { at: now, total, passed, failed, durationS: r?.duration ?? 0 }].slice(-HISTORY_SIZE)
      await $.store.set(historyKey(), next.history)
      // A filtered run says nothing of the full suite's length: keep the run with the most tests.
      const suite = (await $.store.get(suiteKey())) as SuiteRecord | undefined
      if (r?.duration && (!suite || total >= suite.total * 0.9)) await $.store.set(suiteKey(), { total, durationS: r.duration })
    }
    return
  }
  if (prev.tests.state === 'running') next.tests = { ...prev.tests, state: 'idle' }
}

/** Follows the build a button started; true once it has ended. */
async function pollBuild($: EngineInterface, prev: UnitySnapshot, next: UnitySnapshot, now: number, slow: boolean): Promise<boolean> {
  // Ask only around a build: the editor answers the last one forever.
  if (prev.build.state !== 'building' && prev.busy !== 'build' && !slow) return false
  const bs = await cli($, ['build_status'], 20_000)
  if (!bs.ok) return false
  const r = bs.result as { status?: string; result?: string; totalErrors?: number; buildTimeMs?: number } | undefined
  if (r?.status === 'building' || r?.status === 'queued') {
    if (prev.build.state !== 'building') note(next, 'info', t.dash.buildStarted, cfg.buildTarget, now)
    next.build = { state: 'building', startedAt: prev.build.state === 'building' ? (prev.build.startedAt ?? now) : now }
    return false
  }
  if (r?.status !== 'completed') return false
  // Right after the button, the editor may still answer the previous build's result.
  if (prev.build.state === 'building' && prev.build.startedAt && now - prev.build.startedAt < BUILD_GRACE_MS) return false
  next.build = { state: 'done', result: r.result, errors: r.totalErrors, durationS: r.buildTimeMs ? r.buildTimeMs / 1000 : prev.build.durationS }
  if (prev.build.state !== 'building') return prev.busy === 'build'
  const ok = r.result === 'Succeeded'
  note(next, ok ? 'ok' : 'bad', ok ? t.dash.buildSucceeded : t.dash.buildFailed, r.buildTimeMs ? minutes(r.buildTimeMs / 1000) : r.result, now)
  $.ui.toast(ok ? t.buildDone : t.buildFailed(r.result ?? t.failed), { timeoutMs: 12_000 })
  return true
}

// ---------- the buttons' actions ----------

async function beginBusy($: EngineInterface, busy: BusyKind): Promise<boolean> {
  // Claimed before any await: two quick presses never both start.
  if (acting) {
    $.ui.toast(t.alreadyBusy(t.busy[acting]))
    return false
  }
  acting = busy
  const s = filled(await read($, snapshot))
  if (s.busy) {
    acting = null
    $.ui.toast(t.alreadyBusy(t.busy[s.busy as BusyKind] ?? s.busy))
    return false
  }
  const at = await $.clock.now()
  await update($, snapshot, v => ({ ...v, busy, busySince: at, note: undefined }))
  return true
}

async function endBusy($: EngineInterface, busy: BusyKind, text: string, keepBusy = false) {
  if (acting === busy) acting = null
  const at = await $.clock.now()
  await update($, snapshot, v => {
    const release = v.busy === busy && !keepBusy
    const s = { ...filled(v), busy: release ? undefined : v.busy, busySince: release ? undefined : v.busySince, note: text }
    // Tests and builds log their own start and end once the editor reports them.
    if (busy !== 'tests' && busy !== 'build') note(s, 'info', capitalize(t.busy[busy]), text, at)
    return s
  })
  $.ui.toast(text)
  await poll($)
}

const psQuote = (s: string) => `'${s.replace(/'/g, "''")}'`
const shQuote = (s: string) => `'${s.replace(/'/g, `'\\''`)}'`

/** Starts a program detached from this session (Unity, an installer window), on each system its own way. */
async function launchDetached($: EngineInterface, file: string, args: string[]): Promise<boolean> {
  let command: string[]
  if (isWindows) {
    const list = args.length > 0 ? ` -ArgumentList ${args.map(psQuote).join(',')}` : ''
    command = ['powershell', '-NoProfile', '-Command', `Start-Process -FilePath ${psQuote(file)}${list}`]
  } else {
    // A macOS editor is an app bundle, opened by `open`; elsewhere the binary runs in the background.
    const app = /^(.*?\.app)(\/|$)/.exec(file)?.[1]
    command = app ? ['open', '-n', app, '--args', ...args] : ['sh', '-c', `nohup ${[file, ...args].map(shQuote).join(' ')} >/dev/null 2>&1 &`]
  }
  try {
    return (await $.process.run(command, { timeoutMs: 30_000 })).exitCode === 0
  } catch {
    return false
  }
}

async function openUnity($: EngineInterface) {
  if (!root) return
  if (!(await beginBusy($, 'open'))) return
  // Never a second editor on a project that is already open.
  if ((await cli($, ['editor_status'], 15_000)).ok) {
    await endBusy($, 'open', t.alreadyOpen)
    return
  }
  if (!editorPath) await findEditor($)
  if (!editorPath) {
    await endBusy($, 'open', t.editorNotInstalled(editorVersion ?? ''))
    return
  }
  // -projectPath wants the system's own spelling; Start-Process needs the quotes to keep a path with spaces whole.
  const projectArg = isWindows ? `"${root.replace(/\//g, '\\')}"` : root
  const ok = await launchDetached($, editorPath, ['-projectPath', projectArg])
  // Stays busy until the editor answers (a poll clears it); a minute or two on a big project.
  await endBusy($, 'open', ok ? t.unityStarting : t.unityLaunchFailed, ok)
}

async function installEditor($: EngineInterface) {
  if (!cliPath || !editorVersion) return
  if (!(await beginBusy($, 'install-editor'))) return
  if (isWindows) {
    // A visible window: the download is long and the person follows it there.
    const ok = await launchDetached($, 'powershell', ['-NoExit', '-Command', `& ${psQuote(cliPath)} install ${editorVersion}`])
    await endBusy($, 'install-editor', ok ? t.editorInstallStarted(editorVersion) : t.editorInstallFailed)
    return
  }
  await update($, snapshot, v => ({ ...v, note: t.editorInstallRunning(editorVersion ?? '') }))
  let text: string
  try {
    const run = await $.process.run([cliPath, 'install', editorVersion, '--no-banner'], { timeoutMs: 2 * 3600_000 })
    text = run.exitCode === 0 ? t.editorInstallDone(editorVersion) : t.editorInstallFailed
  } catch {
    text = t.editorInstallFailed
  }
  await update($, snapshot, v => ({ ...v, setup: undefined }))
  await endBusy($, 'install-editor', text)
}

async function installCli($: EngineInterface) {
  if (!(await beginBusy($, 'install-cli'))) return
  let text: string
  try {
    const command = isWindows
      ? ['powershell', '-NoProfile', '-ExecutionPolicy', 'Bypass', '-Command', CLI_INSTALL_WINDOWS]
      : ['bash', '-c', CLI_INSTALL_UNIX]
    const run = await $.process.run(command, { timeoutMs: 600_000 })
    const version = await findCli($)
    text = version ? t.cliInstalled(version) : t.cliInstallNotFound(run.exitCode)
  } catch (err) {
    text = t.cliInstallFailed(String(err))
  }
  await update($, snapshot, v => ({ ...v, setup: undefined }))
  await endBusy($, 'install-cli', text)
}

async function installPipeline($: EngineInterface) {
  if (!root || !cliPath) return
  if (!(await beginBusy($, 'install-pipeline'))) return
  let text: string
  try {
    const run = await $.process.run([cliPath, 'pipeline', 'install', '--project-path', root, '--no-banner'], { timeoutMs: 300_000 })
    text = run.exitCode === 0 ? t.pipelineAdded : t.pipelineRefused((run.stderr || run.stdout).trim().split('\n').pop() ?? String(run.exitCode))
  } catch (err) {
    text = t.pipelineFailed(String(err))
  }
  await update($, snapshot, v => ({ ...v, setup: undefined }))
  await endBusy($, 'install-pipeline', text)
}

async function recompile($: EngineInterface) {
  if (!(await beginBusy($, 'recompile'))) return
  // A compile mid-suite reloads the domain under the test runner and can take the editor down.
  if (working(filled(await read($, snapshot)))) {
    await endBusy($, 'recompile', t.waitForWork)
    return
  }
  // The domain reload a compile starts can cut the editor's reply: a timeout here still means the request went through.
  const r = await cli($, ['eval', '--code',
    'UnityEditor.AssetDatabase.Refresh(); UnityEditor.Compilation.CompilationPipeline.RequestScriptCompilation(); return 1;'], 15_000)
  const asked = r.ok || /timed out|timeout|connection|reset|closed/i.test(r.error ?? '')
  await endBusy($, 'recompile', asked ? t.recompileRequested : t.recompileRefused(r.error ?? ''))
}

async function runAllTests($: EngineInterface) {
  if (!(await beginBusy($, 'tests'))) return
  const s = filled(await read($, snapshot))
  let text: string
  if (s.tests.state === 'running') text = t.suiteAlreadyRunning
  else if (s.build.state === 'building') text = t.waitForBuild
  else if (s.playMode === 'playing' || s.playMode === 'paused') text = t.stopPlayFirst
  else {
    const r = await cli($, ['run_tests', '--async_tests', 'true', '--mode', cfg.testMode])
    text = r.ok ? t.suiteStarted(cfg.testMode === 'editmode' ? 'EditMode' : 'PlayMode') : t.runRefused(r.error ?? '')
  }
  await endBusy($, 'tests', text)
}

/** Stops a running suite; the first press only arms it, so a stray click never throws away a long run. */
async function cancelTests($: EngineInterface) {
  const now = await $.clock.now()
  if (armedUntil < now) {
    armedUntil = now + ARM_MS
    await update($, snapshot, v => ({ ...v, note: t.confirmCancelNote }))
    // Redraw once the window closes, so the button reads "Stop the tests" again.
    $.clock.after(ARM_MS + 100, () => void disarm($))
    return
  }
  armedUntil = 0
  if (!(await beginBusy($, 'cancel'))) return
  const r = await cli($, ['cancel_tests'], 30_000)
  await endBusy($, 'cancel', r.ok ? t.testsStopping : t.runRefused(r.error ?? ''))
}

async function disarm($: EngineInterface) {
  await update($, snapshot, v => ({ ...v, note: v.note === t.confirmCancelNote ? undefined : v.note }))
}

async function unblock($: EngineInterface) {
  if (!(await beginBusy($, 'unblock'))) return
  // Cancelling a live run is not unblocking it.
  if (!canUnblock(filled(await read($, snapshot)))) {
    await endBusy($, 'unblock', t.waitForWork)
    return
  }
  await cli($, ['cancel_tests'])
  // Back on the first scene of the build list, and no InitTestScene left behind by an aborted run.
  const r = await cli($, ['eval', '--code',
    'var b=UnityEditor.EditorBuildSettings.scenes; ' +
    'if(b.Length>0 && UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene().path!=b[0].path) UnityEditor.SceneManagement.EditorSceneManager.OpenScene(b[0].path); ' +
    'foreach(var g in UnityEditor.AssetDatabase.FindAssets("InitTestScene", new[]{"Assets"})){var p=UnityEditor.AssetDatabase.GUIDToAssetPath(g); ' +
    'if(p.StartsWith("Assets/InitTestScene")) UnityEditor.AssetDatabase.DeleteAsset(p);} return 1;'])
  await endBusy($, 'unblock', r.ok ? t.unblocked : t.unblockPartial(r.error ?? ''))
}

async function buildPlayer($: EngineInterface) {
  if (cfg.buildTarget === 'off') return
  if (!(await beginBusy($, 'build'))) return
  if (working(filled(await read($, snapshot)))) {
    await endBusy($, 'build', t.testsRunningNoBuild)
    return
  }
  const r = await cli($, ['build', '--confirm', 'true', '--outputPath', `Builds/${projectName}.apk`, '--target', cfg.buildTarget])
  if (!r.ok) {
    await endBusy($, 'build', t.buildRefused(r.error ?? ''))
    return
  }
  const startedAt = await $.clock.now()
  await update($, snapshot, v => ({ ...v, build: { state: 'building' as const, startedAt } }))
  // Stays busy until pollBuild sees the build end.
  await endBusy($, 'build', t.buildStarted(cfg.buildTarget), true)
}

async function runAction($: EngineInterface, k: ActionKey) {
  switch (k) {
    case 'install-cli': return installCli($)
    case 'install-editor': return installEditor($)
    case 'install-pipeline': return installPipeline($)
    case 'open-unity': return openUnity($)
    case 'recompile': return recompile($)
    case 'tests': return runAllTests($)
    case 'build': return buildPlayer($)
    case 'unblock': return unblock($)
    case 'cancel-tests': return cancelTests($)
  }
}

async function toggleDetails($: EngineInterface, which: Exclude<DetailsView, 'none'>) {
  await update($, details, cur => (cur === which ? 'none' : which))
}

async function openPane($: EngineInterface, focus: boolean) {
  if (focus) await $.ui.open({ id: PANE, title: `Unity · ${projectName}`, focus: true })
  else await $.ui.open({ id: PANE, title: `Unity · ${projectName}` })
  void poll($)
}

async function start($: EngineInterface) {
  isWindows = Boolean(await $.env.get('LOCALAPPDATA')) || (await $.env.get('OS')) === 'Windows_NT'
  t = pick(cfg.language === 'auto' ? await detectLanguage($) : cfg.language)
  await $.command.register({ name: 'unity', description: t.commandDescription })
  await findProject($)
  // A reload drops the module's pending actions: a busy flag left in the session's state would never clear.
  await update($, snapshot, v => ({ ...filled(v), busy: undefined, busySince: undefined }))
  if (root) {
    $.clock.every(POLL_MS, () => void poll($))
    if (cfg.openOnStart) void openPane($, false)
    else void poll($)
  }
}

// ---------- the hooks ----------

export const register: Register = (on, options) => {
  cfg = readConfig(options)
  if (cfg.language !== 'auto') t = pick(cfg.language)

  on('session.start', async ($, e, next) => {
    await start($)
    return next(e)
  })

  on('command.run', { command: 'unity' }, async $ => {
    if (!root) await findProject($)
    if (!root) return { text: t.notUnityProject }
    await openPane($, true)
    return { text: t.paneOpened }
  })

  // Typing just "unity" in a Unity project opens the pane instead of asking the model.
  on('prompt.submit', async ($, e, next) => {
    if (root && e.text.trim().toLowerCase() === 'unity') {
      await openPane($, true)
      return { drop: t.paneOpened }
    }
    return next(e)
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const els = $.ui.resolve(e)
    const { Box, Text, Button } = els
    try {
      const s = filled(await read($, snapshot))
      if (!root) return <Text color={K.muted}>{t.notUnityProjectShort}</Text>
      const now = await $.clock.now()
      const suite = (await $.store.get(suiteKey())) as SuiteRecord | undefined
      const cols = e.props.bodyColumns ?? 60
      const narrow = cols < NARROW_COLUMNS
      const v = view(now)
      const action = actionFor(v, s, now, suite)
      const ed = editorBadge(t, s)
      const g = s.git
      const shown = await read($, details)
      const activity = s.activity ?? []
      const failedNames = s.tests.state === 'done' ? (s.tests.failedNames ?? []) : []

      // Icons where the surface draws SVG (desktop, editor, phone); a coloured glyph in the terminal.
      const Svg = 'Svg' in els ? els.Svg : undefined
      // An Svg with an empty alt is drawn as nothing: each icon names what it shows.
      const glyph = (name: IconName, tone: Tone, size: number, alt: string) =>
        Svg ? <Svg source={icon(name, tone, size)} alt={alt} width={size} height={size} /> : null
      const mark = (tone: Tone, name: IconName, size: number, alt: string) =>
        Svg
          ? <Svg source={statusMark(tone, name, size)} alt={alt} width={size} height={size} />
          : <Text color={toneKey(tone)} bold>{toneGlyphText(tone)}</Text>
      const panel = { borderStyle: 'round', borderColor: K.frame, paddingX: 1 } as const

      const heroLine = [
        g ? t.dash.filesChanged(g.dirty) : t.dash.noRepo,
        g?.lastCommit?.split(' ')[0],
        g?.commitAt ? ago(t, g.commitAt, now) : undefined,
      ].filter(Boolean).join(' · ')

      // Two cards a row when narrow, four when wide; each a framed column of the theme's colours.
      const barWidth = Math.max(8, Math.floor(cols / (narrow ? 2 : 4)) - 8)
      const cardViews = cardsFor(v, s, now, suite).map(c => (
        <Box key={`card-${c.title}`} {...panel} flexDirection="column" width={narrow ? '48%' : '23%'} flexGrow={1}>
          <Box flexDirection="row" alignItems="center" columnGap={1}>
            {glyph(c.icon, 'muted', 20, c.title)}
            <Text color={K.text} bold>{c.title}</Text>
          </Box>
          <Text color={toneKey(c.badge.tone)} bold>● {c.badge.text}</Text>
          <Text color={K.text} wrap="truncate-end">{c.detail}</Text>
          {c.progress !== undefined ? <Text color={toneKey(c.badge.tone)}>{bar(c.progress, barWidth)}</Text> : null}
          {c.history && c.history.length > 0
            ? <Text>{c.history.map((ok, i) => <Text key={`h${i}`} color={toneKey(ok ? 'ok' : 'bad')}>■</Text>)}</Text>
            : c.footer.text
              ? <Text color={toneKey(c.footer.tone)} wrap="truncate-end">{c.footer.text}</Text>
              : null}
        </Box>
      ))

      const buttons = buttonsFor(v, s, action).map(b => (
        <Button key={b.key} variant={b.primary ? 'primary' : undefined} hotkey={b.hotkey} onPress={() => runAction($, b.action)}>{b.label}</Button>
      ))
      const busyLine = s.busy ? `◐ ${t.busy[s.busy as BusyKind] ?? s.busy}…` : undefined

      return (
        <Box flexDirection="column" rowGap={1}>
          <Box flexDirection="row" alignItems="center" columnGap={1}>
            {Svg ? <Svg source={logo(20)} alt="Unity Watch" width={20} height={20} /> : null}
            <Text color={K.accent} bold>UNITY WATCH</Text>
            <Box flexGrow={1} />
            <Text color={toneKey(ed.tone)} bold>● {ed.text}</Text>
          </Box>

          <Box {...panel} flexDirection="row" alignItems="center" columnGap={2} paddingY={Svg ? 1 : 0}>
            {glyph('cube', 'accent', 40, projectName)}
            <Box flexDirection="column" flexShrink={1}>
              <Text color={K.muted}>{t.dash.currentProject}</Text>
              <Text>
                <Text color={K.text} bold>{projectName}</Text>
                {g?.branch ? <Text color={K.accent}>{`  · ${g.branch}`}</Text> : null}
              </Text>
              <Text color={K.muted} wrap="truncate-end">{heroLine}</Text>
            </Box>
          </Box>

          <Box flexDirection="row" alignItems="center" columnGap={1}>
            {glyph('pulse', 'accent', 16, t.dash.systemState)}
            <Text color={K.text} bold>{t.dash.systemState}</Text>
          </Box>
          <Box flexDirection="row" flexWrap="wrap" columnGap={1} rowGap={1}>{cardViews}</Box>

          <Box flexDirection="row" flexWrap="wrap" columnGap={2}>
            {DETAIL_VIEWS.map(w => (
              <Button key={`details-${w}`} plain dimColor={shown !== w} onPress={() => toggleDetails($, w)}>
                {`${shown === w ? '▾' : '▸'} ${detailsTitle(t, w)}`}
              </Button>
            ))}
          </Box>
          {shown !== 'none'
            ? <Box {...panel} flexDirection="column">
                <Text color={K.text} bold>{detailsTitle(t, shown)}</Text>
                {detailRows(v, s, shown, now, suite).map((row, i) => (
                  <Box key={`d${i}`} flexDirection="row" columnGap={2}>
                    <Box width={16} flexShrink={0}><Text color={K.muted}>{row[0]}</Text></Box>
                    <Box flexShrink={1}><Text color={row[2] ? toneKey(row[2]) : K.text} wrap="wrap">{row[1]}</Text></Box>
                  </Box>
                ))}
              </Box>
            : null}

          {failedNames.length > 0
            ? <Box {...panel} borderColor={toneKey('bad')} flexDirection="column">
                <Text color={toneKey('bad')} bold>{t.dash.failedTests}</Text>
                {failedNames.slice(0, 8).map((n, i) => <Text key={`ft${i}`} color={K.text} wrap="truncate-end">✗ {shortTest(n)}</Text>)}
                {failedNames.length > 8 ? <Text color={K.muted}>+{failedNames.length - 8}</Text> : null}
              </Box>
            : null}

          <Box {...panel} flexDirection="column">
            <Box flexDirection="row" columnGap={1}>
              <Text color={K.text} bold>{t.dash.recentActivity}</Text>
              <Box flexGrow={1} />
              {activity[0] ? <Text color={K.muted}>{ago(t, activity[0].at, now)}</Text> : null}
            </Box>
            {activity.length === 0 ? <Text color={K.muted}>{t.dash.noActivity}</Text> : null}
            {activity.slice(0, narrow ? 4 : 6).map((a, i) => (
              <Box key={`a${i}`} flexDirection="row" alignItems="center" columnGap={2} marginTop={Svg ? 1 : 0}>
                {mark(a.tone, toneGlyph(a.tone), 26, a.title)}
                <Box flexDirection="column" flexGrow={1} flexShrink={1}>
                  <Text color={K.text} bold wrap="truncate-end">{a.title}</Text>
                  {a.detail ? <Text color={K.muted} wrap="truncate-end">{a.detail}</Text> : null}
                </Box>
                <Text color={K.muted}>{clock(a.at)}</Text>
              </Box>
            ))}
          </Box>

          <Box {...panel} borderColor={toneKey(action.tone)} paddingY={Svg ? 1 : 0}
            flexDirection={narrow ? 'column' : 'row'} alignItems={narrow ? 'flex-start' : 'center'} columnGap={2} rowGap={1}>
            <Box flexDirection="row" alignItems="center" columnGap={2} flexGrow={1} flexShrink={1}>
              {mark(action.tone, action.glyph, 48, action.head)}
              <Box flexDirection="column" flexShrink={1}>
                <Text color={toneKey(action.tone)} bold>{action.head}</Text>
                <Text color={K.muted} wrap="wrap">{busyLine ?? action.sub}</Text>
              </Box>
            </Box>
            <Box flexDirection="row" flexWrap="wrap" columnGap={1} alignSelf={narrow ? 'center' : 'auto'} justifyContent="center">
              {buttons}
            </Box>
          </Box>

        </Box>
      )
    } catch (err) {
      // Shown in the pane itself: a refused or failing drawing otherwise leaves it blank.
      $.ui.log(`unity-watch: ${String(err)}`)
      return <Text color={toneKey('bad')}>{t.paneError(String(err))}</Text>
    }
  })
}

