// Colours and icons. Text and borders name the person's theme colours, so the
// pane follows a light, dark or colour-blind theme like the app around it. An
// SVG cannot name theme keys, so icons use mid tones that read on light and
// dark backgrounds alike.

export type Tone = 'ok' | 'warn' | 'bad' | 'info' | 'muted' | 'accent'

/** A tone as one of the theme's own colour keys, for Text and Box borders. */
export const toneKey = (tone: Tone): string =>
  tone === 'ok' ? 'success' : tone === 'warn' ? 'warning' : tone === 'bad' ? 'error' : tone === 'info' ? 'suggestion' : tone === 'accent' ? 'claude' : 'inactive'

/** The theme keys the pane draws text and frames with. */
export const K = { text: 'text', muted: 'inactive', frame: 'inactive', accent: 'claude' } as const

/** Mid tones for SVG, readable on light and dark backgrounds. */
const SVG_TONES: Record<Tone, string> = {
  ok: '#16a34a',
  warn: '#d97706',
  bad: '#dc2626',
  info: '#2563eb',
  muted: '#6b7280',
  accent: '#ea580c',
}

export const toneHex = (tone: Tone) => SVG_TONES[tone]

// ---------- icons (24 × 24, stroked) ----------

export type IconName = 'cube' | 'flask' | 'folder' | 'phone' | 'pulse' | 'check' | 'cross' | 'alert' | 'clock' | 'play' | 'download'

const ICON_PATHS: Record<IconName, string> = {
  cube: 'M12 2.5 20.5 7.25v9.5L12 21.5 3.5 16.75v-9.5Z M3.5 7.25 12 12l8.5-4.75 M12 12v9.5',
  flask: 'M9 3h6 M10 3v6.2L4.6 18.4A1.8 1.8 0 0 0 6.2 21h11.6a1.8 1.8 0 0 0 1.6-2.6L14 9.2V3 M7.2 15h9.6',
  folder: 'M3 7a2 2 0 0 1 2-2h4.2l2 2.2H19a2 2 0 0 1 2 2V17a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z',
  phone: 'M8 2.5h8a2 2 0 0 1 2 2v15a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2v-15a2 2 0 0 1 2-2Z M11 18.5h2',
  pulse: 'M2 12h4.5l2.5-7 4.5 14 3-7H22',
  check: 'M5 12.5l4.5 4.5L19 7.5',
  cross: 'M6.5 6.5l11 11 M17.5 6.5l-11 11',
  alert: 'M12 7.5v6 M12 17h.01',
  clock: 'M12 7v5l3.2 2 M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Z',
  play: 'M8 5.5v13l10.5-6.5Z',
  download: 'M12 4v11 M7 10.5l5 5 5-5 M5 20h14',
}

/** One icon as a `<g>` at (x, y), `size` px. */
function iconAt(name: IconName, x: number, y: number, size: number, color: string, width = 1.8): string {
  const k = size / 24
  return `<g transform="translate(${x} ${y}) scale(${k})" fill="none" stroke="${color}" stroke-width="${width}" stroke-linecap="round" stroke-linejoin="round"><path d="${ICON_PATHS[name]}"/></g>`
}

/** A lone icon, as its own SVG document. */
export function icon(name: IconName, tone: Tone, size = 20): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 24 24">${iconAt(name, 0, 0, 24, toneHex(tone))}</svg>`
}

/** The mod's mark: an orange cube in a hexagon. */
export function logo(size = 28): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 32 32">
<defs><linearGradient id="lg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#ffb35c"/><stop offset="1" stop-color="#f26b0f"/></linearGradient></defs>
<path d="M16 1.5 28.5 8.75v14.5L16 30.5 3.5 23.25V8.75Z" fill="url(#lg)"/>
<path d="M16 7.5 23.5 11.75v8.5L16 24.5 8.5 20.25v-8.5Z M8.5 11.75 16 16l7.5-4.25 M16 16v8.5" fill="none" stroke="#1a0d02" stroke-width="2" stroke-linejoin="round"/>
</svg>`
}

/** A round status mark: a ring of `tone` around its glyph, `size` px. */
export function statusMark(tone: Tone, glyph: IconName, size = 56): string {
  const c = toneHex(tone)
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 64 64">
<circle cx="32" cy="32" r="28" fill="${c}" fill-opacity="0.14" stroke="${c}" stroke-width="3"/>
${iconAt(glyph, 18, 18, 28, c, 2.6)}
</svg>`
}

/** The terminal's stand-in for a status mark. */
export const toneGlyphText = (tone: Tone) => (tone === 'ok' ? '✓' : tone === 'bad' ? '✕' : tone === 'warn' ? '!' : '◷')

files.hooks/core.ts:
// Everything the pane decides, as pure functions of plain values: how a poll's
// reading merges with what the buttons wrote meanwhile, what each card and the
// action block say, which buttons a state allows, and how the CLI's and git's
// answers parse. register.tsx does the I/O and the drawing; tests/ drive these.

import type { ActivityItem, ConsoleState, DetailsView, GitState, UnitySnapshot } from '../types'
import type { IconName, Tone } from './art'

/** One status card, as the pane draws it. */
export type CardInput = {
  icon: IconName
  title: string
  badge: { text: string; tone: Tone }
  detail: string
  footer: { text: string; tone: Tone }
  /** 0..1: a bar under the detail line. */
  progress?: number
  /** Recent results, oldest first: squares in the footer instead of its text. */
  history?: boolean[]
}
import type { BusyKind, Lang, Strings } from './strings'

export const ACTIVITY_SIZE = 8
export const HISTORY_SIZE = 12
/** A "running" run with the editor stopped and a silent log this long is a ghost. */
export const GHOST_MS = 60_000
/** How long after the Build button an old "completed" answer is taken for the previous build. */
export const BUILD_GRACE_MS = 15_000

/** How long each action may hold the pane busy before a poll lets it go (a crash, a lost reply). */
export const BUSY_LIMIT_MS: Record<BusyKind, number> = {
  open: 5 * 60_000,
  'install-editor': 3 * 3600_000,
  'install-cli': 11 * 60_000,
  'install-pipeline': 6 * 60_000,
  recompile: 60_000,
  tests: 2 * 60_000,
  unblock: 2 * 60_000,
  build: 3 * 3600_000,
  cancel: 60_000,
}

export const initial: UnitySnapshot = {
  isReachable: false,
  isHung: false,
  isCompiling: false,
  isGhost: false,
  tests: { state: 'idle' },
  history: [],
  build: { state: 'idle' },
  initScenes: 0,
  updatedAt: 0,
}

/**
 * The snapshot with every field present. The host keeps the value across
 * reloads, so one written by an older version of this mod lacks newer fields.
 */
export function filled(s: Partial<UnitySnapshot> | undefined): UnitySnapshot {
  return {
    ...initial,
    ...s,
    tests: s?.tests ?? initial.tests,
    history: Array.isArray(s?.history) ? s.history : [],
    build: s?.build ?? initial.build,
    initScenes: s?.initScenes ?? 0,
  }
}

/** Puts a line at the top of the pane's recent activity. */
export function note(s: UnitySnapshot, tone: ActivityItem['tone'], title: string, detail: string | undefined, at: number) {
  s.activity = [{ at, tone, title, detail }, ...(s.activity ?? [])].slice(0, ACTIVITY_SIZE)
}

// ---------- configuration ----------

export type Config = {
  language: 'auto' | Lang
  openOnStart: boolean
  statusLine: boolean
  testMode: 'playmode' | 'editmode'
  buildTarget: 'Android' | 'off'
}

export function readConfig(options: Readonly<Record<string, unknown>>): Config {
  const str = (k: string) => (typeof options[k] === 'string' ? (options[k] as string) : undefined)
  const bool = (k: string, d: boolean) => (typeof options[k] === 'boolean' ? (options[k] as boolean) : d)
  const language = str('language')
  return {
    language: language === 'en' || language === 'fr' ? language : 'auto',
    openOnStart: bool('openOnStart', true),
    statusLine: bool('statusLine', true),
    testMode: str('testMode') === 'editmode' ? 'editmode' : 'playmode',
    buildTarget: str('buildTarget') === 'off' ? 'off' : 'Android',
  }
}

/** What the drawing functions need beside the snapshot: the words, the settings, and what the module found. */
export type View = {
  t: Strings
  testMode: Config['testMode']
  buildTarget: Config['buildTarget']
  editorVersion?: string
  cliPath?: string | null
  logPath?: string
  root?: string | null
  /** "Stop the tests" was pressed once and waits for the second press. */
  armed?: boolean
}

// ---------- formatting ----------

export function clock(ms: number): string {
  const d = new Date(ms)
  return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`
}

export function minutes(s: number): string {
  if (s < 60) return `${Math.round(s)} s`
  const m = Math.round(s / 60)
  return m < 60 ? `${m} min` : `${Math.floor(m / 60)} h ${String(m % 60).padStart(2, '0')}`
}

export function ago(t: Strings, ms: number, now: number): string {
  const s = Math.max(0, (now - ms) / 1000)
  if (s < 45) return t.justNow
  if (s < 3600) return t.minutesAgo(Math.round(s / 60))
  if (s < 86_400) return t.hoursAgo(Math.floor(s / 3600))
  return t.onDate(new Date(ms).toLocaleDateString(t.dateLocale), clock(ms))
}

export function bar(ratio: number, width: number): string {
  const r = Math.min(1, Math.max(0, ratio))
  const full = Math.round(r * width)
  return '█'.repeat(full) + '░'.repeat(Math.max(0, width - full))
}

/** "Ns.Class.Method_name" reads better as "Class › Method name". */
export function shortTest(name: string): string {
  const dot = name.lastIndexOf('.')
  if (dot < 0) return name.replace(/_/g, ' ')
  return `${name.slice(0, dot).split('.').pop()} › ${name.slice(dot + 1).replace(/_/g, ' ')}`
}

export const capitalize = (s: string) => s.charAt(0).toUpperCase() + s.slice(1)

/** The title the "starting Unity" activity line carries. */
export const openingTitle = (t: Strings) => capitalize(t.busy.open)

// ---------- parsing ----------

export type CliAnswer = { ok: boolean; result?: unknown; error?: string }

/** `unity cmd … --json`: success, and the result, which some commands give as JSON text. */
export function parseCliOutput(stdout: string, failed: string): CliAnswer {
  const parsed = JSON.parse(stdout) as {
    success?: boolean
    data?: { result?: unknown } | null
    errors?: { message?: string }[]
  }
  if (!parsed.success) return { ok: false, error: parsed.errors?.[0]?.message ?? failed }
  let result = parsed.data?.result
  if (typeof result === 'string') {
    try {
      result = JSON.parse(result)
    } catch {
      // plain text result: keep it as is
    }
  }
  return { ok: true, result }
}

/** The CLI found an editor process, but its pipeline server did not answer: busy, a modal, or hung. */
export const isHungAnswer = (a: CliAnswer) => !a.ok && /Found a running Unity Editor|not responding|timed out|timeout/i.test(a.error ?? '')

/** The test class the log names last: the one a running suite is in. */
export function currentGroup(tail: string): string | undefined {
  const all = [...tail.matchAll(/Assets\/[^\s:()]*?(\w+Tests?)\.cs/g)]
  return all.length > 0 ? all[all.length - 1]?.[1] : undefined
}

/** `git status --porcelain -b` and `git log -1 --format=%h|%ct|%s`. */
export function parseGit(status: string, log: string | undefined): GitState {
  const lines = status.split('\n').filter(l => l.trim().length > 0)
  const head = lines[0] ?? ''
  const [hash, time, ...subject] = log ? log.trim().split('|') : []
  return {
    branch: /^## (?:No commits yet on )?([^.\s]+)/.exec(head)?.[1],
    ahead: Number(/ahead (\d+)/.exec(head)?.[1] ?? 0),
    behind: Number(/behind (\d+)/.exec(head)?.[1] ?? 0),
    dirty: Math.max(0, lines.length - 1),
    lastCommit: hash ? `${hash} ${subject.join('|')}` : undefined,
    commitAt: time ? Number(time) * 1000 : undefined,
  }
}

/** The `console` command's entries, counted. */
export function parseConsole(result: unknown): ConsoleState | undefined {
  if (typeof result !== 'object' || result === null) return undefined
  const r = result as Record<string, unknown>
  const items = (r.entries ?? r.logs ?? r.messages ?? []) as { type?: string; message?: string }[]
  if (!Array.isArray(items)) return undefined
  const kind = (k?: string) => (k ?? '').toLowerCase()
  const errs = items.filter(i => ['error', 'exception', 'assert'].includes(kind(i.type)))
  const warns = items.filter(i => kind(i.type) === 'warning')
  const last = errs.slice(-3).reverse().map(i => (i.message ?? '').split('\n')[0]?.slice(0, 140) ?? '')
  return { errors: errs.length, warnings: warns.length, last }
}

export const compileFailedIn = (result: unknown) => JSON.stringify(result ?? null).includes('"compilationFailed":true')

// ---------- one poll's write ----------

export type PollMerge = {
  /** The project the poll read. */
  root: string
  /** The snapshot the poll started from. */
  prev: UnitySnapshot
  /** The busy flags the poll saw end (the editor answered, the build ended). */
  clear: BusyKind[]
  /** A note the poll leaves (a failed compile). */
  leaveNote?: string
  now: number
  t: Strings
}

/**
 * The snapshot a poll writes: its reading (`next`, whose `activity` holds only
 * its own new lines) over what stands now (`cur`). A poll takes seconds; what
 * the buttons wrote meanwhile (busy, note, their activity lines, a build they
 * started, a setup they reset) wins over the poll's stale copy of it.
 */
export function mergePoll(cur: Partial<UnitySnapshot> | undefined, next: UnitySnapshot, m: PollMerge): UnitySnapshot {
  const c = filled(cur)
  const keep = c.project?.root === m.root
  const out: UnitySnapshot = { ...next }
  let activity = [...(next.activity ?? []), ...(keep ? (c.activity ?? []) : [])]
  // The editor is up: a "starting Unity…" line is history, not news.
  if (out.isReachable) activity = activity.filter(x => x.title !== openingTitle(m.t))
  out.activity = activity.slice(0, ACTIVITY_SIZE)
  out.busy = keep ? c.busy : undefined
  out.busySince = keep ? c.busySince : undefined
  out.note = m.leaveNote ?? (keep ? c.note : undefined)
  const busy = out.busy as BusyKind | undefined
  const limit = busy ? (BUSY_LIMIT_MS[busy] ?? 60_000) : 0
  if (busy && (m.clear.includes(busy) || (out.busySince !== undefined && m.now - out.busySince > limit))) {
    out.busy = undefined
    out.busySince = undefined
  }
  if (keep && c.build.state === 'building' && m.prev.build.state !== 'building' && next.build.state !== 'building') out.build = c.build
  if (keep && c.setup === undefined && m.prev.setup !== undefined) out.setup = undefined
  return out
}

// ---------- what the state allows ----------

/** A suite or a build is running: nothing may recompile, start another run or build over it. */
export const working = (s: UnitySnapshot) => s.tests.state === 'running' || s.build.state === 'building'

/** A stuck runner, or test scenes left behind by a run that is over (a live run has its own). */
export const canUnblock = (s: UnitySnapshot) => s.isGhost || (s.initScenes > 0 && s.tests.state !== 'running')

export function editorWord(t: Strings, s: UnitySnapshot): string {
  if (s.updatedAt === 0) return '…'
  if (!s.isReachable) return s.isHung ? t.notResponding : t.closed
  if (s.isCompiling) return t.compiling
  if (s.playMode === 'playing') return t.inPlay
  if (s.playMode === 'paused') return t.paused
  return t.ready
}

/** The editor's state as a badge (short) and a header label (long). */
export function editorBadge(t: Strings, s: UnitySnapshot): { text: string; long: string; tone: Tone } {
  if (s.updatedAt === 0) return { text: '…', long: '…', tone: 'muted' }
  if (s.busy === 'open' && !s.isReachable) return { text: t.dash.badgeStarting, long: t.dash.badgeStarting, tone: 'warn' }
  if (!s.isReachable) {
    return s.isHung
      ? { text: t.dash.badgeHung, long: t.dash.notResponding, tone: 'warn' }
      : { text: t.dash.badgeClosed, long: t.dash.disconnected, tone: 'bad' }
  }
  if (s.isCompiling) return { text: t.dash.badgeCompiling, long: t.dash.connected, tone: 'warn' }
  if (s.playMode === 'playing') return { text: t.dash.badgePlay, long: t.dash.connected, tone: 'info' }
  if (s.playMode === 'paused') return { text: t.dash.badgePaused, long: t.dash.connected, tone: 'info' }
  return { text: t.dash.badgeReady, long: t.dash.connected, tone: 'ok' }
}

/** The longest run seen (most tests), the ETA's base for the next one. */
export type SuiteRecord = { total: number; durationS: number }

export function testsProgress(t: Strings, s: UnitySnapshot, now: number, suite: SuiteRecord | undefined) {
  const el = s.tests.startedAt ? (now - s.tests.startedAt) / 1000 : 0
  const ratio = suite && suite.durationS > 0 ? Math.min(0.99, el / suite.durationS) : undefined
  const pct = ratio !== undefined ? `${Math.round(ratio * 100)} %` : minutes(el)
  const left = suite ? t.remaining(minutes(Math.max(0, suite.durationS - el))) : ''
  return { ratio, elapsedS: el, text: `${pct}${left}` }
}

export function statusLine(t: Strings, s: UnitySnapshot, now: number): string {
  const parts = [`Unity ${editorWord(t, s)}`]
  if (s.tests.state === 'running') {
    const el = s.tests.startedAt ? (now - s.tests.startedAt) / 1000 : 0
    parts.push(s.isGhost ? t.testsStuck : t.testsFor(minutes(el)))
  } else if (s.tests.state === 'done' && s.tests.total !== undefined) {
    parts.push(t.testsFor(`${s.tests.passed}/${s.tests.total}${(s.tests.failed ?? 0) > 0 ? ' ✗' : ' ✓'}`))
  }
  if (s.build.state === 'building') parts.push(t.buildRunning)
  else if (s.apk) parts.push(t.lastBuildAt(clock(s.apk.mtimeMs)))
  if (s.console && s.console.errors > 0) parts.push(t.errorsShort(s.console.errors))
  return parts.join(' · ')
}

// ---------- the action block and its buttons ----------

export type ActionKey =
  | 'install-cli'
  | 'install-editor'
  | 'install-pipeline'
  | 'open-unity'
  | 'recompile'
  | 'tests'
  | 'build'
  | 'unblock'
  | 'cancel-tests'

export const HOTKEYS: Partial<Record<ActionKey, string>> = {
  'open-unity': 'o',
  recompile: 'r',
  tests: 't',
  build: 'b',
  unblock: 'u',
  'cancel-tests': 's',
}

export function actionLabel(v: View, k: ActionKey): string {
  const t = v.t
  switch (k) {
    case 'install-cli': return t.installCli
    case 'install-editor': return t.installEditor(v.editorVersion ?? '')
    case 'install-pipeline': return t.installPipeline
    case 'open-unity': return t.openUnity
    case 'recompile': return t.recompile
    case 'tests': return t.allTests
    case 'build': return `${t.build} ${v.buildTarget}`
    case 'unblock': return t.unblock
    case 'cancel-tests': return v.armed ? t.confirmCancel : t.cancelTests
  }
}

export type Action = { tone: Tone; glyph: IconName; head: string; sub: string; keys: ActionKey[] }

/** The block at the bottom: the one thing that matters now, and the buttons for it. */
export function actionFor(v: View, s: UnitySnapshot, now: number, suite: SuiteRecord | undefined): Action {
  const t = v.t
  const setup = s.setup
  // Before the first reading nothing is known: above all, no "closed" and no Open Unity.
  if (s.updatedAt === 0 || !setup) return { tone: 'info', glyph: 'clock', head: t.dash.headLoading, sub: t.dash.subLoading, keys: [] }
  if (!setup.hasCli) return { tone: 'bad', glyph: 'download', head: t.dash.headCli, sub: t.dash.subCli, keys: ['install-cli'] }
  if (!setup.editorPath) {
    return { tone: 'warn', glyph: 'download', head: t.dash.headEditor(v.editorVersion ?? '?'), sub: t.dash.subEditor, keys: ['install-editor'] }
  }
  if (!setup.hasPipeline) return { tone: 'warn', glyph: 'download', head: t.dash.headPipeline, sub: t.dash.subPipeline, keys: ['install-pipeline'] }
  if (!s.isReachable && s.busy === 'open') return { tone: 'warn', glyph: 'clock', head: t.dash.headStarting, sub: t.dash.subStarting, keys: [] }
  if (!s.isReachable && s.isHung) return { tone: 'warn', glyph: 'alert', head: t.dash.headHung, sub: t.dash.subHung, keys: [] }
  if (!s.isReachable) return { tone: 'bad', glyph: 'play', head: t.dash.headClosed, sub: t.dash.subClosed, keys: ['open-unity'] }
  if (s.isGhost) return { tone: 'bad', glyph: 'alert', head: t.dash.headStuck, sub: t.dash.subStuck, keys: ['unblock'] }
  if (s.tests.state === 'running') {
    const sub = [s.tests.group, testsProgress(t, s, now, suite).text].filter(Boolean).join(' · ')
    return { tone: 'warn', glyph: 'clock', head: t.dash.headTests, sub, keys: ['cancel-tests'] }
  }
  if (s.build.state === 'building') {
    return { tone: 'warn', glyph: 'clock', head: t.dash.headBuild, sub: s.build.startedAt ? minutes((now - s.build.startedAt) / 1000) : '', keys: [] }
  }
  if (s.compileFailed) return { tone: 'bad', glyph: 'cross', head: t.dash.headCompile, sub: s.console?.last[0] ?? t.dash.subCompile, keys: ['recompile'] }
  if (s.tests.state === 'done' && (s.tests.failed ?? 0) > 0) {
    return { tone: 'bad', glyph: 'cross', head: t.dash.headFailed(s.tests.failed ?? 0), sub: t.dash.subFailed, keys: ['tests'] }
  }
  const keys: ActionKey[] = v.buildTarget === 'off' ? ['tests'] : ['tests', 'build']
  // Errors a run or a script logged: worth a look, but nothing is broken.
  if (s.console && s.console.errors > 0) {
    return { tone: 'warn', glyph: 'alert', head: t.dash.headConsole(s.console.errors), sub: s.console.last[0] ?? '', keys }
  }
  return { tone: 'ok', glyph: 'check', head: t.dash.headReady, sub: t.dash.subReady, keys }
}

export type ButtonSpec = { key: string; action: ActionKey; label: string; hotkey?: string; primary: boolean }

/** The action block's buttons, then the others the state allows; never one that would disturb a run or a build. */
export function buttonsFor(v: View, s: UnitySnapshot, action: Action): ButtonSpec[] {
  const out: ButtonSpec[] = action.keys.map(k => ({ key: k, action: k, label: actionLabel(v, k), hotkey: HOTKEYS[k], primary: true }))
  if (!s.isReachable) return out
  for (const k of ['tests', 'build', 'recompile', 'unblock'] as const) {
    if (action.keys.includes(k)) continue
    if (k === 'build' && v.buildTarget === 'off') continue
    if (k === 'unblock' ? !canUnblock(s) : working(s)) continue
    out.push({ key: `more-${k}`, action: k, label: actionLabel(v, k), hotkey: HOTKEYS[k], primary: false })
  }
  return out
}

export const toneGlyph = (tone: Tone): IconName => (tone === 'ok' ? 'check' : tone === 'bad' ? 'cross' : tone === 'warn' ? 'alert' : 'clock')

// ---------- the cards ----------

/** The four status cards: Unity, tests, project, build. */
export function cardsFor(v: View, s: UnitySnapshot, now: number, suite: SuiteRecord | undefined): CardInput[] {
  const t = v.t
  const setup = s.setup
  const ed = editorBadge(t, s)
  const cliVersion = (setup?.cliVersion ?? '').replace(/^[^\d]*/, '')
  const unity: CardInput = {
    icon: 'cube',
    title: t.dash.unity,
    badge: { text: ed.text, tone: ed.tone },
    detail: setup?.editorPath || !setup ? `Unity ${v.editorVersion ?? '?'}` : t.dash.noEditor(v.editorVersion ?? '?'),
    footer: !setup ? { text: '…', tone: 'muted' }
      : !setup.hasCli ? { text: t.dash.noCli, tone: 'bad' }
        : !setup.hasPipeline ? { text: t.dash.noPipeline, tone: 'warn' }
          : { text: t.dash.cliFooter(cliVersion), tone: 'ok' },
  }

  const history = s.history.map(h => h.failed === 0)
  let tests: CardInput
  if (s.tests.state === 'running') {
    const p = testsProgress(t, s, now, suite)
    tests = {
      icon: 'flask',
      title: t.dash.tests,
      badge: s.isGhost ? { text: t.dash.badgeStuck, tone: 'bad' } : { text: t.dash.badgeRunning, tone: 'warn' },
      detail: p.text,
      progress: p.ratio,
      footer: { text: s.tests.group ?? '', tone: 'info' },
    }
  } else if (s.tests.state === 'done' && s.tests.total !== undefined) {
    const failed = s.tests.failed ?? 0
    tests = {
      icon: 'flask',
      title: t.dash.tests,
      badge: failed === 0 ? { text: `${s.tests.passed}/${s.tests.total}`, tone: 'ok' } : { text: t.dash.badgeFailed(failed), tone: 'bad' },
      detail: [s.tests.durationS ? minutes(s.tests.durationS) : '', s.tests.endedAt ? ago(t, s.tests.endedAt, now) : ''].filter(Boolean).join(' · '),
      footer: { text: '', tone: 'muted' },
      history,
    }
  } else {
    tests = { icon: 'flask', title: t.dash.tests, badge: { text: t.dash.badgeNone, tone: 'muted' }, detail: t.dash.noRun, footer: { text: '', tone: 'muted' }, history }
  }

  const g = s.git
  const consoleFooter: CardInput['footer'] = !s.console ? { text: t.dash.consoleUnknown, tone: 'muted' }
    : s.console.errors > 0 ? { text: t.dash.consoleErrors(s.console.errors), tone: 'bad' }
      : { text: t.dash.consoleOk, tone: 'ok' }
  const project: CardInput = g
    ? {
      icon: 'folder',
      title: t.dash.project,
      badge: g.dirty === 0 ? { text: t.dash.badgeClean, tone: 'ok' } : { text: t.dash.badgeChanges(g.dirty), tone: 'warn' },
      detail: `${g.branch ?? '?'} · ${g.lastCommit?.split(' ')[0] ?? ''}${g.ahead > 0 ? ` ↑${g.ahead}` : ''}${g.behind > 0 ? ` ↓${g.behind}` : ''}`,
      footer: consoleFooter,
    }
    : { icon: 'folder', title: t.dash.project, badge: { text: t.dash.badgeNone, tone: 'muted' }, detail: t.dash.noRepo, footer: consoleFooter }

  let build: CardInput
  if (s.build.state === 'building') {
    build = {
      icon: 'phone',
      title: t.dash.build,
      badge: { text: t.dash.badgeRunning, tone: 'warn' },
      detail: s.build.startedAt ? minutes((now - s.build.startedAt) / 1000) : '…',
      footer: { text: v.buildTarget.toUpperCase(), tone: 'warn' },
    }
  } else if (s.apk) {
    const lastFailed = s.build.state === 'done' && s.build.result !== 'Succeeded'
    build = {
      icon: 'phone',
      title: t.dash.build,
      badge: lastFailed ? { text: t.dash.badgeBuildFailed, tone: 'bad' } : { text: t.dash.badgeAvailable, tone: 'ok' },
      detail: `${s.apk.name} · ${Math.round(s.apk.size / 1048576)} ${t.megabytes}`,
      footer: { text: ago(t, s.apk.mtimeMs, now).toUpperCase(), tone: lastFailed ? 'bad' : 'ok' },
    }
  } else {
    build = {
      icon: 'phone',
      title: t.dash.build,
      badge: { text: t.dash.badgeNone, tone: 'muted' },
      detail: t.dash.noBuildFile,
      footer: { text: v.buildTarget.toUpperCase(), tone: 'muted' },
    }
  }
  return [unity, tests, project, build]
}

// ---------- a card's details ----------

export const DETAIL_VIEWS = ['unity', 'tests', 'project', 'build'] as const

export function detailsTitle(t: Strings, v: DetailsView): string {
  return v === 'unity' ? t.dash.unity : v === 'tests' ? t.dash.tests : v === 'project' ? t.dash.project : v === 'build' ? t.dash.build : ''
}

export type DetailRow = [label: string, value: string, tone?: Tone]

/** One card's details as label / value / tone rows. */
export function detailRows(v: View, s: UnitySnapshot, which: DetailsView, now: number, suite: SuiteRecord | undefined): DetailRow[] {
  const t = v.t
  const d = t.dash
  const rows: DetailRow[] = []
  if (which === 'unity') {
    const setup = s.setup
    rows.push([d.dState, editorWord(t, s), editorBadge(t, s).tone])
    rows.push([d.dVersion, v.editorVersion ?? '?'])
    rows.push([d.dEditor, setup?.editorPath ?? d.dMissing, setup?.editorPath ? undefined : 'bad'])
    rows.push([d.dCli, setup?.hasCli ? `${setup.cliVersion ?? ''} · ${v.cliPath ?? ''}` : d.dMissing, setup?.hasCli ? undefined : 'bad'])
    rows.push([d.dPipeline, setup?.hasPipeline ? d.dInstalled : d.dMissing, setup?.hasPipeline ? 'ok' : 'warn'])
    rows.push([d.dCompile, s.compileFailed ? d.dFailed : s.isCompiling ? t.compiling : d.dOk, s.compileFailed ? 'bad' : 'ok'])
    if (v.logPath) rows.push([d.dLog, v.logPath])
  } else if (which === 'tests') {
    if (s.tests.state === 'running') {
      rows.push([d.dState, `${t.testsRunning} · ${testsProgress(t, s, now, suite).text}`, 'warn'])
      if (s.tests.group) rows.push([d.dGroup, s.tests.group])
    }
    if (suite) rows.push([d.dSuite, `${suite.total} tests · ${minutes(suite.durationS)}`])
    rows.push([d.dMode, v.testMode === 'editmode' ? 'EditMode' : 'PlayMode'])
    for (const h of [...s.history].reverse().slice(0, 6)) {
      rows.push([`${new Date(h.at).toLocaleDateString(t.dateLocale)} ${clock(h.at)}`, `${h.passed}/${h.total} · ${minutes(h.durationS)}`, h.failed === 0 ? 'ok' : 'bad'])
    }
    if (s.history.length === 0 && s.tests.state !== 'running') rows.push([d.dRuns, d.noRun])
    for (const n of (s.tests.state === 'done' ? (s.tests.failedNames ?? []) : []).slice(0, 5)) rows.push(['✗', shortTest(n), 'bad'])
  } else if (which === 'project') {
    const g = s.git
    if (g) {
      rows.push([d.dBranch, `${g.branch ?? '?'}${g.ahead > 0 ? ` ↑${g.ahead}` : ''}${g.behind > 0 ? ` ↓${g.behind}` : ''}`])
      rows.push([d.dChanges, d.filesChanged(g.dirty), g.dirty === 0 ? 'ok' : 'warn'])
      if (g.lastCommit) rows.push([d.dCommit, `${g.lastCommit}${g.commitAt ? ` · ${ago(t, g.commitAt, now)}` : ''}`])
    } else rows.push([d.dBranch, d.noRepo])
    rows.push([d.dPath, v.root ?? ''])
    if (s.console) {
      rows.push([d.dConsole, `${t.consoleErrors(s.console.errors)}${t.consoleWarnings(s.console.warnings)}`, s.console.errors > 0 ? 'bad' : 'ok'])
      for (const m of s.console.last) rows.push(['✗', m, 'bad'])
    }
    if (s.initScenes > 0) rows.push([d.dLeftovers, t.leftoverScenes(s.initScenes), 'warn'])
  } else if (which === 'build') {
    rows.push([d.dTarget, v.buildTarget])
    if (s.build.state === 'building') {
      rows.push([d.dState, `${t.building} · ${s.build.startedAt ? minutes((now - s.build.startedAt) / 1000) : ''}`, 'warn'])
    } else if (s.build.state === 'done') {
      const parts = `${s.build.result ?? '?'}${s.build.durationS ? ` · ${minutes(s.build.durationS)}` : ''}${s.build.errors ? ` · ${s.build.errors} err.` : ''}`
      rows.push([d.dLastBuild, parts, s.build.result === 'Succeeded' ? 'ok' : 'bad'])
    }
    if (s.apk) rows.push([d.dFile, `Builds/${s.apk.name} · ${Math.round(s.apk.size / 1048576)} ${t.megabytes} · ${ago(t, s.apk.mtimeMs, now)}`])
    else rows.push([d.dFile, d.noBuildFile])
  }
  return rows
}

