/** What the Unity test runner is doing, as the pane shows it. */
export type TestRun = {
  state: 'idle' | 'running' | 'done'
  /** When this mod first saw the run going (ms since epoch). */
  startedAt?: number
  /** The test class the editor log names last while it runs. */
  group?: string
  total?: number
  passed?: number
  failed?: number
  durationS?: number
  /** When the last run ended (ms since epoch). */
  endedAt?: number
  /** Full names of the failed tests of the last finished run. */
  failedNames?: string[]
}

/** One finished test run, for the history strip. */
export type RunRecord = {
  at: number
  total: number
  passed: number
  failed: number
  durationS: number
}

/** The last Android build the editor reports. */
export type BuildRun = {
  state: 'idle' | 'building' | 'done'
  result?: string
  errors?: number
  startedAt?: number
  durationS?: number
}

/** The git tree of the project. */
export type GitState = {
  branch?: string
  ahead: number
  behind: number
  dirty: number
  lastCommit?: string
  /** When the last commit was made (ms since epoch). */
  commitAt?: number
}

/** What the Unity console holds. */
export type ConsoleState = {
  errors: number
  warnings: number
  /** First line of the latest errors, newest first. */
  last: string[]
}

/** What this machine and project have of the Unity toolchain. */
export type SetupState = {
  /** The Unity CLI answers (`unity --version`). */
  hasCli: boolean
  cliVersion?: string
  /** The project's manifest lists com.unity.pipeline, which the CLI drives the editor through. */
  hasPipeline: boolean
  /** The editor version ProjectSettings/ProjectVersion.txt asks for. */
  editorVersion?: string
  /** That version's Unity.exe, when installed. */
  editorPath?: string
}

/** One line of the pane's recent activity. */
export type ActivityItem = {
  at: number
  tone: 'ok' | 'warn' | 'bad' | 'info'
  title: string
  detail?: string
}

/** One poll of everything the pane shows. */
export type UnitySnapshot = {
  /** The Unity project the session sits in; absent outside one. */
  project?: { root: string; name: string }
  setup?: SetupState
  /** False when no editor answers the pipeline (closed, crashed or hung). */
  isReachable: boolean
  /** An editor process is there but its pipeline does not answer (busy importing, a modal, hung). */
  isHung: boolean
  status?: string
  playMode?: string
  isCompiling: boolean
  /** A run that says "running" while the editor sits in edit mode with a silent log. */
  isGhost: boolean
  tests: TestRun
  history: RunRecord[]
  build: BuildRun
  apk?: { mtimeMs: number; size: number; name: string }
  git?: GitState
  console?: ConsoleState
  /** Leftover InitTestScene files in Assets. */
  initScenes: number
  /** An action a button started and is still waiting on. */
  busy?: string
  /** When that action started (ms since epoch); a poll lets a stale one go. */
  busySince?: number
  /** The last compile the editor reports failed. */
  compileFailed?: boolean
  /** The last thing an action said. */
  note?: string
  /** What happened lately, newest first. */
  activity?: ActivityItem[]
  updatedAt: number
}

/** Which card's details the dashboard shows. */
export type DetailsView = 'none' | 'unity' | 'tests' | 'project' | 'build'

declare module 'claude-code' {
  interface PluginState {
    'unity-watch': { snapshot: UnitySnapshot; details: DetailsView }
  }
}
